Consider a linear stochastic system of the form
\begin{equation}\label{sys}
x_{t+1} = Ax_t + B u_t + w_t, \quad t = 1, 2, \ldots,
\end{equation}
where $x_t \in \mathbb{R}^n$ is the system input, and $u_t \in \mathbb{R}^{n_u}$ is the control input.

\begin{equation}\label{sys}
x_{t+1} = Ax_t + B u_t + w_t, \quad t = 1, 2, \ldots,
\end{equation}

\label{ass:noise}
For every $t=1, 2, \ldots$, the random vector $w_t$ satisfies the following properties:
\begin{enumerate}
\item The probability density function (pdf) of noise $p_w (\cdot)$ is known and twice differentiable. Additionally, $\underline m I_n \preceq -\nabla^2  \log p_w(\cdot)  \preceq \overline m I_n.$ for some $\underline m, \overline m>0$.


\item $\mathbb{E} [w_t ] = 0$ and $\mathbb{E} [w_t w_t^\top ] = \mathbf{W}$, where $\mathbf{W}$ is positive definite.
 \end{enumerate}

We consider the infinite-horizon average cost LQ setting with the following cost function:
\begin{equation}
J_\pi (\theta) := \limsup_{T \to \infty} \frac{1}{T} \mathbb{E}_\pi \bigg [
\sum_{t=1}^T c (x_t, u_t)
\bigg ].
\end{equation}

\label{lqr}
Suppose that $(A, B)$ is stabilizable,
and $(A, Q^{1/2})$ is observable. 
Then, the following algebraic Riccati equation (ARE) has a unique positive definite solution $P^*(\theta)$:
\begin{equation}\label{ric}
\begin{split}
P^*(\theta) &= Q + A^\top P^*(\theta) A - A^\top P^*(\theta) B (R + B^\top P^*(\theta) B)^{-1} B^\top P^*(\theta) A.
\end{split}
\end{equation}
Furthermore, the optimal cost function is given by
$J (\theta) = \mathrm{tr} (\mathbf{W} P^*(\theta))$,
which is  continuously differentiable with respect to $\theta$,
and
the optimal policy is uniquely obtained as
$\pi_* (x; \theta) = K(\theta) x$,
where the control gain matrix $K(\theta)$ is given by $K(\theta) := - (R + B^\top P^*(\theta) B)^{-1} B^\top P^*(\theta) A$.

\begin{equation}\label{ric}
\begin{split}
P^*(\theta) &= Q + A^\top P^*(\theta) A - A^\top P^*(\theta) B (R + B^\top P^*(\theta) B)^{-1} B^\top P^*(\theta) A.
\end{split}
\end{equation}

\begin{equation}\label{posterior}
\begin{split}
p(\theta | h_{t+1}) &\propto p(x_{t+1} | z_t, \theta ) p(\theta |h_t) = p_w (x_{t+1} - \Theta^{\top}  z_t ) p(\theta  | h_t).
\end{split}
\end{equation}

The Langevin dynamics takes the form of 
\begin{equation}\label{eq:cont}
dX_\tau = - \nabla U(X_\tau) \mathrm{d}\tau + \sqrt{2} \mathrm{d} B_\tau,
\end{equation}
where  $B_\tau$ denotes the standard Brownian motion in $\mathbb{R}^{n_x}$.

To solve for $X_\tau$ numerically, 
we apply the Euler--Maruyama discretization to the Langevin diffusion  and obtain the following \emph{unadjusted Langevin algorithm} (ULA):
\begin{equation}\label{eq:ula}
X_{j+1} = X_j - \gamma_j \nabla U(X_j) + \sqrt{2\gamma_j} W_j,
\end{equation}
where $(W_j)_{j\geq 1}$ is an i.i.d. sequence of standard $n_x$-dimensional Gaussian random vectors, and  $(\gamma_j)_{j\geq 1}$ is a sequence of step  sizes.

With the data $z_t = (x_t, u_t)$ collected, the preconditioner for our problem is defined as
\begin{equation}\label{eq:preconditioner}
P_t:=\lambda I_{dn}+\sum_{s=1}^{t-1} \mathrm{blkdiag}\{z_s z_s^\top\}_{i=1}^n,
\end{equation}
$\mathrm{blkdiag}\{A_i\}_{i=1}^n\in\mathbb{R}^{dn\times dn}$ denotes the block diagonal matrix of $A_i$'s, and $\lambda > 0$ is determined by the prior.

\caption{Thompson sampling with Langevin dynamics for LQR
}
\label{alg:ula}
\begin{algorithmic}[1]
\State {\bf Input:} $p_1$;
\State {\bf Initialization:} $t \leftarrow 1$, $t_0 \leftarrow 0$,
$x_1 \leftarrow 0$, $\mathcal{D} \leftarrow \emptyset$,
$\mathbf{U}_0 \leftarrow U_1$,
$\tilde{{\theta}}_0 \leftarrow arg\,min U_1 (\theta)$, $\theta_{\min, 0} \leftarrow \tilde{\theta}_0$;
\For{Episode $k = 1,2,\ldots$}
\State $T_{k} \leftarrow k+1$, and $t_k \leftarrow t$;

\State $\mathbf{U}_k (\cdot) := \mathbf{U}_{k-1} (\cdot) -\sum_{(z_t, x_{t+1}) \in \mathcal{D}} \log p_w(x_{t+1} -\Theta^\top z_t)$;
\State $\mathcal{D} \leftarrow \emptyset$;

\State $\theta_{\min, k} \in arg\,min \mathbf{U}_k (\theta)$;
\State Compute the preconditioner $\tilde{P}_k$, the step  size $\tilde{\gamma}_k$, and the number of iterations $\tilde{N}_k$;
\While{True}
\State ${\theta}_0 \leftarrow \theta_{\min, k}$;
\For{Step $j=0, 1, \ldots, \tilde{N}_k-1$}
\State Sample ${\theta}_{j+1}$ according to \eqref{ULAstep};
\EndFor

\If{$\theta_{\tilde{N}_k} \in \mathcal{C}$}
\State $\tilde\theta_k\leftarrow\theta_{\tilde{N}_k}$
\State Break;
\EndIf

\EndWhile
\State Compute the gain matrix $K_k := K(\tilde{\theta}_k)$;
\While{ $t \leq t_k + T_{k}-1$}
\State Execute control $u_t = K_k x_t + \nu_t$ for $\nu_t$ satisfying Assumption~\ref{ass:perturb};
\State Observe new state $x_{t+1}$, and update $\mathcal{D} \leftarrow \mathcal{D} \cup \{(z_t, x_{t+1})\}$;
\State  $t \leftarrow t+1$;
\EndWhile
\EndFor
\end{algorithmic}

\label{prop:ula}
Suppose Assumptions~\ref{ass:noise} and~\ref{ass:init_bound} hold. 
Given any trajectory $(z_s)_{s\geq1}$, the exact posterior $\mu_t$ and the approximate posterior $\tilde{\mu}_t$ obtained by preconditioned ULA satisfy 
\[
\mathbb{E}_{\theta_t \sim \mu_t, \tilde{\theta}_t \sim \tilde{\mu}_t}\big[
| \theta_t - \tilde{\theta}_t |^p_{P_t} \mid h_{t}
\big ] \leq D_p
\]
for $p\geq 2$,
where $D_p = \big(\frac{pdn}{m}\big)^{\frac{p}{2}}\big(2^{2p+1}+5^p\big)$. When $p=2$, we further have
\begin{equation}\label{bd:comp}
\mathbb{E}_{\theta_t \sim \mu_t, \tilde{\theta}_t \sim \tilde{\mu}_t}\big[
| \theta_t - \tilde{\theta}_t |^2 \mid h_{t}
\big ]^{\frac{1}{2}} \leq \sqrt{\frac{D}{\max\{\lambda_{\min,t}, t\}}},
\end{equation}
where $D = 114\frac{dn}{m}$ and $\lambda_{\min,t}$ denotes the minimum eigenvalue of $P_t$.

\label{prop:half_exact_true}
Suppose Assumptions~\ref{ass:noise} and~\ref{ass:init_bound} hold. 
Given any trajectory $(z_s)_{s\geq1}$,
\begin{equation}
\begin{split}
    &\mathbb{E}_{\theta_t \sim \mu_t}\big[
    | \theta_t - \theta_* |^p_{P_t} \mid h_{t}
    \big ]^{\frac{1}{p}} \leq 2p \sqrt{\frac{8nM^2}{m^3}\log \bigg(\frac{n}{\delta}\bigg(\frac{\lambda_{\max,t}}{\lambda}\bigg)^{\frac{d}{2}}\bigg)+C}, \quad t >0
\end{split}
\end{equation}
holds with probability at least $1-\delta$ for
any $0<\delta < 1$ and $p \geq 2$, where
the constant $C>0$ depends only on $p$, $m$, $n$, $d$ and $\lambda$, and $\lambda_{\max,t}$ denotes the maximum eigenvalue of $P_t$.

