    \nabla^2_{\theta}U_t = \lambda I_{dn} - \sum_{s=1}^{t-1}\nabla^2_{w_s} \log p_w(x_{s+1}-\Theta^\top z_s) \otimes z_s z_s^{\top}.
\end{equation*} 
