    & = 2 \mathbb{E}\bigg[\bigg(\sup_{0\leq \tau \leq \Delta}e^{\alpha \tau}|\theta_\tau-\theta_*|_{P_t}^2 \bigg(\frac{e^{\alpha \Delta}-1}{\alpha}\bigg)\bigg)^{\frac{1}{2}}\bigg]\\
    & \leq \mathbb{E} \bigg[\bigg(\frac{16 e^{\alpha \Delta}}{\alpha}\bigg)^{\frac{1}{2}}\Big (\sup_{0\leq \tau \leq \Delta}e^{\alpha \tau}|\theta_\tau-\theta_*|_{P_t}^2 \Big )^{\frac{1}{2}} \bigg],
\end{split}
\end{equation}
where the expectation is taken with respect to $\theta_\tau$.
By Young's inequality, we further have
\begin{equation}\nonumber
\begin{split}
