\begin{align*}
    \mathbb{E}\Big [\max_{j\leq t}|x_t|^p\mathbf{1}_{F_t^c}\Big ] &\leq {\mathbb{E}[\mathbf{1}_{F_t^c}]}^{\frac{1}{2}} {\mathbb{E}\Big [\max_{j\leq t}|x_t|^{2p}\Big ]}^{\frac{1}{2}}  \leq {(4\delta)}^{\frac{1}{2}} {\mathbb{E}\Big [\max_{j\leq t}|x_t|^{2p} \Big]}^{\frac{1}{2}}.
\end{align*}
Let $D_t = \Theta_*^{\top}\tilde{K}(\Tilde{\theta}_t)$ and $r_t = B_*\nu_t + w_t$. Then, the linear system can be expressed as
\begin{align*}
    x_t &= D_{t-1}x_{t-1}+r_{t-1}  = D_{t-1}(D_{t-2}x_{t-2}+r_{t-2})+ r_{t-1}\\
    & = D_{t-1}D_{t-2}D_{t-3}x_{t-3} + D_{t-1}D_{t-2}r_{t-3}+ D_{t-1}r_{t-2}+r_{t-1}\\
    & = D_{t-1}D_{t-2}\ldots D_2r_1 + \cdots + D_{t-1}D_{t-2}r_{t-3}+ D_{t-1}r_{t-2} + r_{t-1}\\
    & = \sum_{j=1}^{t-2}\bigg(\prod_{s=j+1}^{t-1}D_s\bigg)r_j +r_{t-1}.
\end{align*}
Since $|D_t| \leq M_{\rho}$, we have
\begin{align*}
    \mathbb{E}\big [|x_t|^{2p}\big ] &= \mathbb{E}\left [\bigg |\sum_{j=1}^{t-2}\bigg(\prod_{s=j+1}^{t-1}D_s\bigg)r_j +r_{t-1} \bigg |^{2p} \right ]\\
    & \leq (t-1)^{2p-1}\mathbb{E} \left [\sum_{j=1}^{t-2}\bigg |\bigg(\prod_{s=j+1}^{t-1}D_s\bigg)r_j \bigg|^{2p}+|r_{t-1} |^{2p} \right ]\\
    & \leq (t-1)^{2p-1}\mathbb{E}\left [\sum_{j=1}^{t-1}M_{\rho}^{2p(t-j-1)}|r_j|^{2p} \right]\\
    & \leq (t-1)^{2p-1}\mathbb{E}\big [|r_t|^{2p}\big ]\frac{M_{\rho}^{2p(t-1)}-1}{M^{2p}_{\rho}-1}\\
    & \leq (t-1)^{2p-1}\mathbb{E}\big [|r_t|^{2p}\big ] M_\rho^{2pt},
\end{align*}
where the second inequality follows from Jensen's inequality.

By Lemma~\ref{lem:state_log} with $\delta = \frac{1}{t^{2p} M_\rho^{2pt}} \leq \frac{1}{t}$, the first term on the right-hand side of \eqref{state_divide} is estimated as
\begin{align*}
    \mathbb{E}\Big [\max_{j \leq t}|x_t|^p\mathbf{1}_{F_t}\Big ] &\leq \mathbb{E}\left [C\left(\log\bigg(\frac{1}{\delta}\bigg)^2\sqrt{\log\bigg(\frac{t}{\delta}\bigg)}\right)^{p(d+1)}\mathbf{1}_{F_t}\right]\\
    &\leq C\left(\log\bigg(\frac{1}{\delta}\bigg)^2\sqrt{\log\bigg(\frac{t}{\delta}\bigg)}\right)^{p(d+1)}
\end{align*}
for some positive constant $C$ depending only on $n,n_u,\rho,M_{\rho},S,\bar{L}_{\nu}, m$ and $M$.

Finally, we obtain that
\begin{align*}
    \mathbb{E}\Big [\max_{j\leq t}|x_t|^{p}\Big ]
    &\leq C\left(\log\bigg(\frac{1}{\delta}\bigg)^2\sqrt{\log\bigg(\frac{t}{\delta}\bigg)}\right)^{p(d+1)}+\sqrt{4\delta}\sqrt{\mathbb{E}[|x_t|^{2p}]}\\
    &\leq C\left (\log\big(t^{2p}M_{\rho}^{2pt}\big)^2\sqrt{\log\bigg(t^{2p+1}M_{\rho}^{2pt}\bigg)}\right)^{p(d+1)} +\sqrt{\mathbb{E}[|r_t|^{2p}]}\\
    & \leq C t^{\frac{5}{2}p(d+1)} + \sqrt{\mathbb{E}[|r_t|^{2p}]}.
\end{align*}
It follows from Jensen's inequality that 
\begin{equation}\nonumber
\begin{split}
\mathbb{E}[|r_t|^{2p}] &\leq  2^{p-1}(S^{2p}\mathbb{E}[|\nu_t|^{2p}] + \mathbb{E}[|w_t|^{2p}])\\
&\leq 2^{p-1}p!\bigg (S^{2p}(4\bar L_{\nu}^2)^p+\Big(\frac{2}{m}\Big )^p\bigg ),
\end{split}    
\end{equation}
where the second inequality holds because $\nu_t$ and $w_t$ are sub-Gaussian. 
Putting everything together, the result follows.

Given $ j \in [1,k]$, let $A_*, B_*$ be the true system parameters and $s \in (t_j,t_{j+1}):=\mathcal{I}_j$. We first define the following quantities for $s\in \mathcal{I}_j$ :
\[
y_s := 
\begin{bmatrix}
    A_*x_{s-1} + B_*u_{s-1}          \\
    K_j(A_*x_{s-1} + B_*u_{s-1})
\end{bmatrix}, 
\]
where $K_j$ denotes the control gain matrix computed at the beginning of $j$th episode.

Writing
\[
L_s := 
\begin{bmatrix}
    I_n & 0\\
    K_j & I_{n_u}
\end{bmatrix},
\quad\text{and}\quad \psi_s :=
\begin{bmatrix}
    w_{s-1}\\
    \nu_{s}
\end{bmatrix},
\]
we can decompose $z_s$ as $z_s= y_s + L_s\psi_s$ by the construction of the algorithm.

For a trajectory $(z_s)_{s\geq 1}$, let us introduce a sequence of random variables up to time $s$, which is denoted by
\[
\tilde h_s:=(x_1,W_1,\nu_1,...,x_{s},W_s,\nu_s),
\]
where $W_s$ denotes randomness incurred by the ULA when triggered, hence, $W_s=0$ if $s \neq t_j$ for some $j$.








Defining the index set 
\[
\mathcal{J}_k:=\{s \in \mathcal{I}_j: j \in[1,k]\},
\]
we consider the modified filtration 
\begin{equation*}
\mathcal{F}'_s:=
\begin{cases}
\sigma(\cup_{j \leq s} \tilde h_j) \quad\text{for}\quad s \in \mathcal{J}_k-\{t_2-1,t_3-1,...,t_k-1\},\\
\sigma(\cup_{j \leq s+1} \tilde h_j) \quad\text{for}\quad s\in \{t_2-1,t_3-1,...,t_k-1\}.
\end{cases}
\end{equation*}
This way we can incorporate the information observed at $s=t_j$ with that made up to $s=t_j-1$ as seen in Figure~\ref{fig:app_e}.



