Yet simple but important observation is that for $\mathcal{J}_k=\{n_i:n_1<n_2<...<n_{\frac{k(k+1)}{2}}\}$ 
both stochastic processes $(L_{n_s})$, $(y_{n_s})$ are $\mathcal{F}'_{n_{s-1}}$-measurable and $(\psi_{n_s})$ is $\mathcal{F}'_{n_s}$-measurable.

To proceed we first notice that
\[
{\lambda_{\min}} \bigg(\lambda I_d+ \sum_{s=1}^{t_{k+1}-1} z_s z_s^\top\bigg) \succeq    {\lambda_{\min}} \bigg(\lambda I_d+\sum_{s \in\mathcal{J}_k} z_s z_s^\top\bigg).
\]
Invoking Lemma \ref{lem:preconditioner_expansion} with $\epsilon=\tilde\lambda=1$ and $\xi_s=L_s \psi_s$, it follows that
\begin{equation}\label{pe}
\begin{split}
&\sum_{s \in\mathcal{J}_k} z_s z_s^{\top}\quad\succeq\\
& \sum_{s\ \in\mathcal{J}_k}  (L_s\psi_s)(L_s\psi_s)^{\top} - \underbrace{\bigg[\sum_{s \in\mathcal{J}_k}  y_s (L_s \psi_s)^{\top}\bigg]^{\top}\bigg [ I_d+\sum_{s \in\mathcal{J}_k} y_sy_s^{\top}\bigg ]^{-1} \bigg [\sum_{s \in\mathcal{J}_k}  y_s (L_s \psi_s)^{\top}\bigg ]}_{(*)} -  I_d.
\end{split}
\end{equation}
Our goal is to find a lower bound of \eqref{pe}. To begin with, define $
\psi_{1,s} = 
\begin{bmatrix}
    w_{s-1}\\
    0
\end{bmatrix}$ and $
\psi_{2,s} = 
\begin{bmatrix}
    0\\
    \nu_{s}
\end{bmatrix}$ for $s\geq 1$ setting $w_0=0$ for simplicity. Noting that $L_s\psi_s = L_s\psi_{1,s} + \psi_{2,s}$, we apply Lemma \ref{lem:preconditioner_expansion} with $\epsilon=\frac{1}{2}$, $\tilde\lambda=1$ to obtain
\begin{equation}\label{pe_aux}
\begin{split}
    &\sum_{s \in\mathcal{J}_k}  (L_s\psi_{s})(L_s\psi_{s})^{\top}
    =\sum_{s \in\mathcal{J}_k}  (L_s\psi_{1,s})(L_s\psi_{1,s})^{\top} + \frac{1}{2}\sum_{s \in\mathcal{J}_k} \psi_{2,s}\psi_{2,s}^{\top}\\
    & - 2\underbrace{\bigg [\sum_{s \in\mathcal{J}_k}  \psi_{2,s} (L_s \psi_{1,s})^{\top}\bigg]^{\top}\bigg[ I_d+\sum_{s \in\mathcal{J}_k} \psi_{2,s}\psi_{2,s}^{\top}\bigg]^{-1}\bigg[\sum_{s \in\mathcal{J}_k}  \psi_{2,s} (L_s \psi_{1,s})^{\top}\bigg]}_{(**)} - \frac{1}{2} I_d.
\end{split}
\end{equation}
The first term of \eqref{pe_aux} is written as
\begin{align*}
    \sum_{s \in\mathcal{J}_k}  (L_s\psi_{1,s})(L_s\psi_{1,s})^{\top} & = \sum_{s \in\mathcal{J}_k}
    \begin{bmatrix}
        w_{s-1} w_{s-1}^{\top} & w_{s-1}(K_{v(s)}w_{s-1})^{\top}\\
        (K_{v(s)}w_{s-1}) w_{s-1}^{\top} & (K_{v(s)}w_{s-1})(K_{v(s)}w_{s-1})^{\top}     
    \end{bmatrix}
    \\
    & =: 
    \begin{bmatrix}
        X^{\top}X & X^{\top}Y\\
        Y^{\top}X & Y^{\top}Y
    \end{bmatrix},
\end{align*}
where $v(s)$ is indicates the episode number such that $s \in \mathcal{I}_{v(s)}$. By Lemma \ref{lem:tall_matrix}, we conclude that
\begin{align}\label{bar-lambda}
    \sum_{s \in\mathcal{J}_k}  (L_s\psi_{1,s})(L_s\psi_{1,s})^{\top} 
     = 
    \begin{bmatrix}
        X^{\top}X & X^{\top}Y\\
        Y^{\top}X & Y^{\top}Y
    \end{bmatrix}
     \succeq 
    \begin{bmatrix}
        \frac{\bar\lambda}{|Y|^2+\bar\lambda}X^{\top}X & 0\\
        0 & -\bar\lambda I_{n_u}
    \end{bmatrix}
\end{align}
for any $\bar\lambda>0$, where $X = [w_{n_1-1}, \cdots, w_{n_{k(k+1)/2}-1}]^{\top}$ and $Y = [K_{\nu(n_1)}w_{n_1-1}, \cdots, K_{\nu(n_{k(k+1)/2})}w_{n_{k(k+1)/2}-1}]^{\top}$.

Next, we invoke Lemma \ref{lem:noise_tail_bound} with $\epsilon=\frac{1}{2}\lambda_{\min}(\mathbf{W})$ for $\psi_s = w_{s-1}$, $\psi_s = \nu_{s}$ respectively to characterize good noise sets. 
Choosing $\rho = \log \frac{2}{\delta}$ in Lemma \ref{lem:noise_tail_bound}, there exists $C>0$ such that for any $\delta>0$ and $k\geq C \sqrt{\log (\frac{2}{\delta}) +d\log 9}$, the following events hold with probability at least $1-\delta$:
\begin{align*}
E_{1,k} &= \bigg\{w \in \Omega : \frac{1}{4}\lambda_{\min}(\mathbf{W}) k(k+1) I_{n} \preceq \sum_{s \in\mathcal{J}_k}  w_{s-1} w_{s-1}^{\top} \preceq \frac{1}{2}(\lambda_{\max}(\mathbf{W}) +\frac{1}{2}\lambda_{\min}(\mathbf{W})) k(k+1) I_{n}\bigg\},\\
E_{2,k} &= \bigg\{\nu \in \Omega_{\nu} : \frac{1}{2}\lambda_{\min}(\mathbf{W})k  I_{n_u} \preceq \sum_{s \in\mathcal{J}_k}  \nu_{s} \nu_{s}^{\top} \preceq (\lambda_{\max}(\mathbf{W}) +\frac{1}{2}\lambda_{\min}(\mathbf{W}))k I_{n_u} \bigg\}.
\end{align*}
Furthermore, from the observation,
\begin{equation*}
\begin{split}
\mathrm{tr}\bigg(\sum_{s \in\mathcal{J}_k} (K_{v(s)} w_{s-1}) (K_{v(s)}w_{s-1})^\top\bigg) &\leq \sum_{s \in\mathcal{J}_k} \mathrm{tr} ((K_{v(s)} w_{s-1}) (K_{v(s)}w_{s-1})^\top)\\
&\leq M_K^2 \sum_{s \in\mathcal{J}_k} |w_{s-1}|^2 \\
&= M_K^2 \mathrm{tr}\bigg(\sum_{s \in\mathcal{J}_k} w_{s-1}w_{s-1}^\top\bigg),
\end{split}
\end{equation*}
we also have the following event {whose subevent is $E_{1,k}$}:
\[E_{3,k} =\bigg \{w \in \Omega :  \sum_{s \in\mathcal{J}_k}  (K_{v(s)} w_{s-1})(K_{v(s)} w_{s-1})^{\top} \preceq \frac{n M_K^2}{2}(\lambda_{\max}(\mathbf{W}) +\frac{1}{2}\lambda_{\min}(\mathbf{W})) k(k+1) I_{n_u}\bigg\}.\]

where $\Omega_\nu \subset \Omega$ denotes the probability space associated with the random sequence $(\nu_s)_{s\geq 1}$ and $\Omega$ is the probability space representing all randomness in the algorithm as defined in the previous subsection. 

To proceed we choose $\bar{\lambda} = \frac{1}{8}\lambda_{\min}(\mathbf{W})k$ in \eqref{bar-lambda} and recall that $|Y|^2 = \lambda _{\max} (Y^\top Y)$. On the event $E_{1,k} \cap E_{2,k} \cap E_{3,k}$, first two terms on the right-hand side of \eqref{pe_aux} is lower bounded as
\begin{align*}
    &\sum_{s \in\mathcal{J}_k}  (L_s\psi_{1,s})(L_s\psi_{1,s})^{\top}+\frac{1}{2}\sum_{s \in\mathcal{J}_k}  \psi_{2,s}\psi_{2,s}^{\top}\\
    &\succeq
    \begin{bmatrix}
    \frac{\bar\lambda}{|Y|^2+\bar\lambda}X^{\top}X & 0\\
    0 & -\bar\lambda I_{n_u}
    \end{bmatrix} + \frac{1}{2}
   \sum_{s\in\mathcal{J}_k} 
   \begin{bmatrix}0 \\ \nu_s  
   \end{bmatrix}
    \begin{bmatrix}
        0 &\nu_s^\top
    \end{bmatrix}\\
    &\succeq
    \begin{bmatrix}
    \frac{\frac{1}{32}\lambda_{\min}^2(\mathbf{W})k^2(k-1)}{\frac{nM_K^2}{2}(\lambda_{\max}(\mathbf{W})+\frac{1}{2}\lambda_{\min}(\mathbf{W}))k(k-1)+\frac{1}{8}\lambda_{\min}(\mathbf{W})} I_{n} &0\\ 
        0 & -\frac{1}{8}\lambda_{\min}(\mathbf{W}) k I_{n_u}
    \end{bmatrix}
    +
    \begin{bmatrix}
        0 & 0\\
        0 & \frac{1}{4}\lambda_{\min}(\mathbf{W})kI_{n_u}
    \end{bmatrix}
    \\
    &= 
    k\begin{bmatrix}
    \frac{\lambda_{\min}^2(\mathbf{W})k(k-1)}{16nM_K^2(\lambda_{\max}(\mathbf{W})+\frac{1}{2}\lambda_{\min}(\mathbf{W}))k(k-1)+4\lambda_{\min}(\mathbf{W})} I_{n}&0\\ 
        0 & \frac{1}{8}\lambda_{\min}(\mathbf{W})I_{n_u}
    \end{bmatrix}
    \\
    &\succeq C k I_{d}
\end{align*}
for some $C>0$. 

We next deal with $(*)$ in \eqref{pe} and $(**)$ in \eqref{pe_aux} together as they have the same  structure. Let us begin by defining 
\[
S_k(\psi_{2},L\psi_{1}) := \bigg[\sum_{s \in\mathcal{J}_k}  \psi_{2,s} (L_s \psi_{1,s})^{\top}\bigg]^{\top}\bigg[I_d+\sum_{s \in\mathcal{J}_k} \psi_{2,s}\psi_{2,s}^{\top}\bigg]^{-1}\bigg[\sum_{s \in\mathcal{J}_k}  \psi_{2,s} (L_s \psi_{1,s})^{\top}\bigg].
\]
Similarly,
\[
S_k(y,L\psi) := \bigg[\sum_{s \in\mathcal{J}_k}  y_s (L_s \psi_{s})^{\top}\bigg]^{\top}\bigg[I_d+\sum_{s \in\mathcal{J}_k} y_s y_s^{\top}\bigg]^{-1}\bigg[\sum_{s \in\mathcal{J}_k}  y_s (L_s \psi_{s})^{\top}\bigg].
\]

Applying Lemma \ref{lem:self-normalized_matrix} with $\rho=\log(\frac{1}{\delta})$ to the stochastic processes $(\psi_s)_{s\in \mathcal{J}_k}$ and $(y_s)_{s\in \mathcal{J}_k}$, each of the following events holds with probability at least $1-\delta$:
\begin{align*}
E_{4,k} &=\bigg \{w \in \Omega, \nu \in \Omega_{\nu}:|S_k(\psi_{2},L\psi_{1})|\leq 7\bar L_{\nu}^2
(M_K^2+2)\log\bigg(\frac{e^d \det(I_d+\sum_{s \in\mathcal{J}_k}\psi_{2,s}\psi_{2,s}^{\top})}{\delta}\bigg)\bigg\},\\
E_{5,k} &=\bigg \{w \in \Omega, \nu \in \Omega_{\nu}:|S_k(y,L\psi)|\leq 7\bar L^2(M_K^2+2)\log\bigg(\frac{e^d \det(I_d+\sum_{s \in\mathcal{J}_k} y_s y_s^{\top})}{\delta}\bigg)\bigg\},
\end{align*}
since $\max_{s \leq t} |L_s| \leq \sqrt{M_K^2+2}$ 
with $L_s := 
\begin{bmatrix}
    I_n & 0\\
    K_j & I_{n_u}
\end{bmatrix}.$ To verify, we recall that $|L_s| = \sqrt{\lambda_{\max}(L_sL_s^{\top})}$. Here,
\[
L_sL_s^{\top} =
\begin{bmatrix}
    I_{n} &K_j^{\top}\\ 
        K_j & K_jK_j^{\top}+I_{n_u}
    \end{bmatrix}.
\]
Fixing $v=\begin{bmatrix}x^{\top} & y^{\top}\end{bmatrix}^{\top}$ such that $|v|=1$ where $x\in\mathbb{R}^n$ and  $y\in\mathbb{R}^{n_u}$, we have
\begin{align*}
    v^{\top}
    \begin{bmatrix}
    I_{n} &K_j^{\top}\\ 
        K_j & K_jK_j^{\top}+I_{n_u}
    \end{bmatrix}
    v
    &\leq  
    |x|^2+2x^{\top}K_j^{\top}y + M_K^2|y|^2 + |y|^2\\
    &\leq (M_K^2+1)(x^2+y^2)+|y|^2\\
    &\leq M_K^2+2.
\end{align*}
\begin{itemize}
\item Bound of $S_k(\psi_2,L\psi_1)$ on $E_{2,k}\cap E_{4,k}$:

On $E_{2,k}$,
\begin{align*}
\det\bigg(I_d+\sum_{s \in\mathcal{J}_k}\psi_{2,s}\psi_{2,s}^{\top}\bigg)^{\frac{1}{d}} &\leq \frac{1}{d}(d+\sum_{s \in\mathcal{J}_k}\psi_{2,s}^{\top}\psi_{2,s})\\
& = \frac{1}{d}(d+\sum_{s \in\mathcal{J}_k}|\nu_{s}|^2)\\
& \leq \frac{n_u}{d}(\lambda_{\max}(\mathbf{W}) +\frac{1}{2}\lambda_{\min}(\mathbf{W}))k+1\\
& \leq C k
\end{align*}
for some $C>0$ where the second inequality follows by
\begin{align*}
\sum_{s\in\mathcal{J}} |\nu_s|^2 =\mathrm{tr}(\sum_{s\in\mathcal{J}_k} \nu_s \nu_s ^\top) &\leq n_u \lambda_{\max}({\sum_{s\in\mathcal{J}_k} \nu_s\nu_s^\top})\\
& \leq n_u(\lambda_{\max}(\mathbf{W}) +\frac{1}{2}\lambda_{\min}(\mathbf{W}))k.
\end{align*}


Altogether, on the event $E_{2,k}\cap E_{4,k}$,
\begin{equation*}
\begin{split}
S_k(\psi_{2},L\psi_{1})&=\bigg|\bigg[\sum_{s \in\mathcal{J}_k} \psi_{2,s} (L_s \psi_{1,s})^{\top}\bigg]^{\top}\bigg[I_d+\sum_{s \in\mathcal{J}_k}\psi_{2,s}\psi_{2,s}^{\top}\bigg]^{-1}\bigg[\sum_{s \in\mathcal{J}_k} \psi_{2,s} (L_s \psi_{1,s})^{\top}\bigg]\bigg|\\
&\leq 7\bar L_{\nu}^2(M_K^2+2)\log\bigg(\frac{Ce^d k^d}{\delta}\bigg).
\end{split}
\end{equation*}

\item Bound of $S_k(y,L\psi)$ on $F_{t_{k+1}} \cap E_{1,k} \cap E_{5,k}$: 

On $E_{1,k}$, 
\begin{align*}
&\det\bigg(I_d+\sum_{s \in\mathcal{J}_k} y_s y_s^{\top}\bigg)^{\frac{1}{d}} \\
&\leq \frac{1}{d}\bigg(d+\sum_{s \in\mathcal{J}_k}|y_s|^2\bigg)\\
& = \frac{1}{d}\bigg(d+\sum_{s \in\mathcal{J}_k}(\underbrace{|x_s-w_{s-1}|^2}_{\leq 2|x_s|^2+2|w_{s-1}|^2}+\underbrace{|K_{v(s)}(x_s-w_{s-1})|^2}_{\leq 2M_K^2|x_s|^2+2M_K^2|w_{s-1}|^2})\bigg)\\
& \leq \frac{1}{d}\bigg(d+\sum_{s \in\mathcal{J}_k}((2+2M_K^2)|x_s|^2+(2+2M_K^2)|w_{s-1}|^2)\bigg)\\
& \leq  \frac{(M_K^2+1)}{d}\bigg(\underbrace{2\sum_{s \in\mathcal{J}_k}|x_s|^2}_\text{(a)}+ \underbrace{n(\lambda_{\max}(\mathbf{W}) +\frac{1}{2}\lambda_{\min}(\mathbf{W}))k(k-1)}_\text{by taking trace in $E_{1,k}$}\bigg)+1,
\end{align*}
where the last inequality follows from
\begin{align*}
\sum_{s\in\mathcal{J}} |w_{s-1}|^2 =\mathrm{tr}\bigg(\sum_{s\in\mathcal{J}_k} w_{s-1} w_{s-1} ^\top\bigg) &\leq n \lambda_{\max}\bigg({\sum_{s\in\mathcal{J}_k} w_{s-1}w_{s-1}^\top}\bigg)\\
& \leq \frac{n}{2}\bigg(\lambda_{\max}(\mathbf{W}) +\frac{1}{2}\lambda_{\min}(\mathbf{W})\bigg)k(k-1).
\end{align*}

To bound (a) above, let us observe that $t_{k+1}=\frac{(k+1)(k+2)}{2} \leq k^p$ for any $p\geq 3$ and consider the event $F_{t_{k+1}} \cap E_{1,k}$. Applying Lemma~\ref{lem:state_log} with $\delta=k^{-p} \leq t_{k+1}^{-1}$, we deduce that
\begin{align*}
   \sum_{s\in\mathcal{J}_k} |x_s|^2=\sum_{s\in\mathcal{J}_k}|x_s|^2 & \leq t_{k+1} \max_{s \leq t_{k+1}}|x_s|^2\\
   &\leq t_{k+1} \bigg( C(\log k)^3 \sqrt{\log k} \bigg)^{2(d+1)}\\
   &\leq C k^2\bigg( k\sqrt{\log k}\bigg)^{2(d+1)}\\
   & \leq C k^{3d+5}
\end{align*}
for some $C>0$ depending on $p\geq 3$ and the constant from Lemma~\ref{lem:state_log}.

Therefore, on the event $F_{t_{k+1}} \cap E_{1,k}\cap E_{5,k}$, we have
\begin{align*}
    \det\bigg(I_d+\sum_{s\in\mathcal{J}_k} y_s y_s^{\top}\bigg)^{\frac{1}{d}}&\leq (M_K^2+1)\bigg(\frac{2C}{d}k^{3d+5}+ \bigg(\lambda_{\max}(\mathbf{W}) +\frac{1}{2}\lambda_{\min}(\mathbf{W})\bigg)k(k-1)\bigg)+1\\
    &\leq C k^{3d+5}
