Combining Theorem~\ref{thm:improved} and Lemma~\ref{lem:r1}, we finally prove Theorem~\ref{thm:regret}, which yields the $O(\sqrt{T})$ regret bound. Recall that the system parameter sampled in Algorithm~\ref{alg:ula} is denoted by $\tilde{\theta}_k$, which is used in obtaining the control gain matrix $K_k = K(\tilde{\theta}_k)$ for $t \in [t_k,t_{k+1})$. Let $P^*_k := P^* (\tilde{\theta}_k)$ for brevity and $\Tilde{u}_t = K_k x_t$ be an optimal action for $\tilde{\theta}_k$. Fix an arbitrary $t \in [t_k, t_{k+1})$. Then, the Bellman equation {\cite{bertsekas2011dynamic}} for $t$ in episode $k$ is given by
\begin{equation}\label{eq:main1}
\begin{split}
&J(\tilde{\theta}_k) + x_t^\top P^*_k x_t\\
 &= 
x_t^{\top} Q x_t + \Tilde{u}_t^{\top} R \Tilde{u}_t + \mathbb{E} [ (\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t+ w_t)^\top P^*_k (\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t + w_t) \mid h_t]\\
&= x_t^{\top} Qx_t + \Tilde{u}_t^{\top}R \Tilde{u}_t +  (\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t )^\top P^*_k(\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t) + \mathbb{E} [ w_t^\top P^*_k w_t \mid h_t],
\end{split}
\end{equation}
where the expectation is taken with respect to $w_t$, and
the second inequality holds because the mean of $w_t$ is zero.
On the other hand, the observed next state is expressed as
\[
x_{t+1} = \bar{\Theta}_*^\top z_t + w_t,
\]
where $\bar{\Theta}_* \in \mathbb{R}^{d \times n}$ is the matrix of the true parameter random variables. 
We then notice that
\begin{equation}\label{eq:main2}
\begin{split}
&\mathbb{E} [ w_t^\top P^*_k w_t \mid h_t]=\mathbb{E} [ x_{t+1}^\top P^*_k x_{t+1} \mid h_t] - 
(\bar{\Theta}_*^\top z_t )^\top P^*_k (\bar{\Theta}_*^\top z_t ).
\end{split}
\end{equation}
Plugging \eqref{eq:main2} into \eqref{eq:main1} and rearranging it,
\begin{equation}\label{eq:main3}
\begin{split}
x_t^{\top} Q x_t + \Tilde{u}_t^{\top} R \Tilde{u}_t  &= J(\tilde{\theta}_k) + x_t^\top P^*_k x_t 
-\mathbb{E} [ x_{t+1}^\top P^*_k x_{t+1} \mid h_t]\\
&+ (\bar{\Theta}_*^\top z_t )^\top P^*_k (\bar{\Theta}_*^\top z_t )
- (\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t )^\top P^*_k (\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t). 
\end{split}
\end{equation}
Since $\Tilde{u}_t = u_t - \nu_t$, we derive that
\begin{equation}\label{eq:main4}
    \Tilde{u}_t^{\top}R\Tilde{u}_t =u_t^{\top}Ru_t -\nu_t^{\top} R \Tilde{u}_t-\Tilde{u}_t^{\top}R\nu_t - \nu_t^{\top} R \nu_t,
\end{equation}
and
\begin{equation}\label{eq:main5}
\begin{split}
  (\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t )^\top P^*_k (\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t) &= (\bar{\Theta}_k^\top z_t )^\top P^*_k (\bar{\Theta}_k^\top z_t )-(\Tilde{B}_k\nu_t)^{\top}P^*_k(\Tilde{A}_kx_t)-(\Tilde{A}_kx_t)^{\top}P^*_k(\Tilde{B}_k\nu_t)\\
    &\quad\quad-(\Tilde{B}_k\nu_t)^{\top}P^*_k(\Tilde{B}_k\tilde{u}_t)-(\Tilde{B}_k\tilde{u}_t)P^*_k(\Tilde{B}_k\nu_t)- \nu_t^{\top} \Tilde{B}_k^{\top}P^*_k\Tilde{B}_k\nu_t.
\end{split}    
\end{equation}
Combining \eqref{eq:main3}, \eqref{eq:main4} and \eqref{eq:main5}, we conclude that 
\begin{equation*}
\begin{split}
\mathbb{E}[c (x_t, u_t)] &= \mathbb{E}[x_t^{\top} Q x_t + u_t^{\top} R u_t] \\
&= J(\tilde{\theta}_k) + x_t^\top P^*_k x_t 
-\mathbb{E} [ x_{t+1}^\top P^*_k x_{t+1} \mid h_t]\\
&+ (\bar{\Theta}_*^\top z_t )^\top P^*_k (\bar{\Theta}_*^\top z_t )
- (\bar{\Theta}_k^\top z_t )^\top P^*_k (\bar{\Theta}_k^\top z_t ) + \mathbb{E}[\nu_t^{\top} \Tilde{B}_k^{\top}P^*_k\Tilde{B}_k\nu_t] +\mathbb{E}[\nu_t^{\top} R \nu_t],
\end{split}
\end{equation*}
where the expectation is taken with respect to $w_t$ and $\nu_t$.

Using this expression and observing $t_{n_T} \leq T \leq t_{n_T+1} - 1$, the expected regret of Algorithm~\ref{alg:ula} is decomposed as
\begin{equation}\nonumber
\begin{split}
R(T) 
& =  \mathbb{E} \bigg [
\sum_{k=1}^{n_T} \sum_{t=t_k}^{t_{k+1} - 1} ( c (x_t, u_t) - J (\bar{\theta}_*))
\bigg ] - \mathbb{E} \bigg [ \sum_{t=T+1}^{t_{n_T+1} - 1} ( c (x_t, u_t) - J (\bar{\theta}_*))  \bigg ]\\&:= R_1 + R_2 + R_3 + R_4 + R_5,
\end{split}
\end{equation}
where
\begin{equation}\nonumber
\begin{split}
R_1 &= \mathbb{E}\bigg[
\sum_{k=1}^{n_T} \sum_{t=t_k}^{t_{k+1} - 1} z_t^\top (
\bar{\Theta}_* P^*_k \bar{\Theta}_*^\top 
- \tilde{\Theta}_k P^*_k\tilde{\Theta}_k^\top 
) z_t 
\bigg ],\\
R_2 &= \mathbb{E}\bigg[
\sum_{k=1}^{n_T} \sum_{t=t_k}^{t_{k+1} - 1} (
x_t^\top P^*_k x_t - 
\mathbb{E} [x_{t+1}^\top P^*_k x_{t+1} | h_t]
)
\bigg ],\\
R_3 &= \mathbb{E} \bigg [
\sum_{k=1}^{n_T} T_k (J (\tilde{\theta}_k) - J(\bar{\theta}_*))
\bigg ],\\
R_4 &=\mathbb{E}\bigg[\sum_{k=1}^{n_T} \sum_{t=t_k}^{t_{k+1} - 1}(\nu_t^{\top} \Tilde{B}_k^{\top}P^*_k\Tilde{B}_k\nu_t +\nu_t^{\top} R \nu_t)\bigg],\\
R_5 &= \mathbb{E} \bigg [ \sum_{t=T+1}^{t_{n_T+1} - 1} (  J (\bar{\theta}_*) - c (x_t, u_t))  \bigg ].
\end{split}
\end{equation}
To obtain the exact regret bound, we include $R_5$  which is not considered in \cite{ouyang2019posterior}.  
By Lemma~\ref{lem:r1}, $R_1$ is bounded as
\[
R_1 \leq 4\sqrt{2}M_{P^*} S\sqrt{D}(C M_K^2+32\bar{L}_{\nu}^2) n_T.
\]
Since $T_k = k+1$, we have
\begin{equation}\nonumber
\begin{split}
T &\geq 1 + \sum_{k=1}^{n_T-1} T_{k} =  \frac{n_T(n_T+1)}{2} \geq\frac{n_T^2}{2},
\end{split}
\end{equation}
which implies that 
\begin{equation}\label{eq:thm:n}
n_T \leq \sqrt{2 T}.
\end{equation} 
Therefore, we conclude that 
\[
R_1 \leq 8M_{P^*} S\sqrt{D}(C M_K^2+32\bar{L}_{\nu}^2) \sqrt{T}.
\]

Regarding $R_2$, we use the tower rule $\mathbb{E} [ \mathbb{E} [ X_t | h_t]] = \mathbb{E} [X_t]$ to obtain 
\begin{equation}\nonumber
\begin{split}
R_2 
&= \mathbb{E}\bigg[
\sum_{k=1}^{n_T} \sum_{t=t_k}^{t_{k+1} - 1} (
x_t^\top P^*_k x_t - 
x_{t+1}^\top P^*_k x_{t+1} 
)
\bigg ] \\
&= \mathbb{E} \bigg [
\sum_{k=1}^{n_T} (
x_{t_k}^\top P^*_k x_{t_k} - 
x_{t_{k+1}}^\top P^*_k x_{t_{k+1}}
)
\bigg ]\\
& \leq \mathbb{E} \bigg [
\sum_{k=1}^{n_T} 
x_{t_k}^\top P^*_k x_{t_k}
\bigg ]\\
&\leq  \mathbb{E} \bigg [
\sum_{k=1}^{n_T} 
M_{P^*} | x_{t_k}|^2
\bigg ]\\
&\leq M_{P^*} C n_T \quad (\because \mbox{Theorem~\ref{thm:improved}})\\
&\leq M_{P^*} C \sqrt{2T},
\end{split}
\end{equation}
where the last inequality follows from \eqref{eq:thm:n}. 

We also need to deal with $R_3$ carefully. What is different from the analysis presented in \cite{ouyang2019posterior}, the term simply vanishes using the intrinsic property of probability matching of Thompson sampling as exact posterior distributions are used. However, in our analysis, approximate posterior is considered instead so a different approach is required. To cope with this problem, we adopt the notion of Lipschitz continuity of $J$ for estimation. Specifically, 
\begin{equation}\nonumber
\begin{split}
R_3 &\leq \mathbb{E} \bigg [
\sum_{k=1}^{n_T} T_k |J (\tilde{\theta}_k) - J(\bar{\theta}_*)| 
\bigg ]\\
&\leq \mathbb{E} \bigg [
\sum_{k=1}^{n_T} T_k L_J  |\tilde{\theta}_k -  \bar{\theta}_*| 
\bigg ]\\
&= \sum_{k=1}^{n_T}  T_k L_J \mathbb{E} \big [ \mathbb{E} [
  |\tilde{\theta}_k -  \bar{\theta}_*|  | h_{t_k} ]
\big ] \\
& \leq \sum_{k=1}^{n_T}  T_k L_J \mathbb{E} \big [ \mathbb{E} [
  |\tilde{\theta}_k -  \bar{\theta}_*|^2  | h_{t_k} ]^{\frac{1}{2}}
\big ]\\
&\leq  \sum_{k=1}^{n_T} L_J \sqrt{D} T_k  \frac{1}{\sqrt{t_k}},
\end{split}
\end{equation}
where $L_J$ is a Lipschitz constant of $J$ and the last inequality follows from Proposition~\ref{prop:ula} with $D = 66\frac{dn}{m}$. 

Using the bound~\eqref{eq:lem1:t} of $\sum_{k=1}^{n_T} \frac{T_k}{\sqrt{t_k}}$ in the proof of Lemma~\ref{lem:r1}, we have
\begin{equation}\nonumber
\begin{split}
R_3 &\leq \sqrt{2}  L_J \sqrt{D} n_T\\
&\leq 2  L_J \sqrt{D} \sqrt{T}.
\end{split}
\end{equation}
By the definition of $\nu_t$, $R_4$ is bounded as
\begin{equation}\nonumber
\begin{split}
R_4 &=\mathbb{E}\bigg[\sum_{k=1}^{n_T} \sum_{t=t_k}^{t_{k+1} - 1}(\nu_t^{\top} \Tilde{B}_k^{\top}P^*_k\Tilde{B}_k\nu_t +\nu_t^{\top} R \nu_t)\bigg]\\
&\leq \mathbb{E}\bigg[\sum_{k=1}^{n_T}\sum_{t=t_k}^{t_{k+1} - 1}(S^2M_{P^*}+|R|)|\nu_t|^2\bigg]\\
&\leq \sum_{k=1}^{n_T}(S^2M_{P^*}+|R|)\mathrm{tr}(\mathbf{W})\\
&\leq (S^2M_{P^*}+|R|)\mathrm{tr}(\mathbf{W})n_T\\
&\leq (S^2M_{P^*}+|R|)\mathrm{tr}(\mathbf{W})\sqrt{2T},
\end{split}    
\end{equation}
where $M_{P^*}$ satisfies $P^*(\theta)\leq M_{P^*}$ for $\theta\in\mathcal{C}$. 
Lastly, $R_5$ is bounded as
\begin{equation}\nonumber
\begin{split}
R_5 &= \mathbb{E} \bigg [ \sum_{t=T+1}^{t_{n_T+1} - 1} (  J (\bar{\theta}_*) - c (x_t, u_t))  \bigg ]\\
&\leq \mathbb{E} \bigg [ \sum_{t=T+1}^{t_{n_T+1} - 1}  J (\bar{\theta}_*) \bigg ]\\
&\leq (t_{n_T+1} - T-1 )M_J\\
&\leq (T_{n_T}-1) M_J \quad (\because t_{n_T} \leq T \leq t_{n_T +1} - 1)\\
&\leq M_J n_T \\
&\leq M_J \sqrt{2T},
\end{split}
\end{equation}
where $M_J$ satisfies $J(\theta)\leq M_J$ for $\theta \in \mathcal{C}$.
Putting all the bounds together, we conclude that
\begin{equation}\nonumber
\begin{split}
R(T) &\leq C \sqrt{T}, 
 \end{split}
\end{equation}
and thus the result follows. One novelty in our analysis is that the concentration of approximate posterior is naturally embedded into the analysis, which eventually drops the $\log T$ term in the resulting regret.

\begin{equation}\label{eq:main1}
\begin{split}
&J(\tilde{\theta}_k) + x_t^\top P^*_k x_t\\
 &= 
x_t^{\top} Q x_t + \Tilde{u}_t^{\top} R \Tilde{u}_t + \mathbb{E} [ (\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t+ w_t)^\top P^*_k (\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t + w_t) \mid h_t]\\
&= x_t^{\top} Qx_t + \Tilde{u}_t^{\top}R \Tilde{u}_t +  (\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t )^\top P^*_k(\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t) + \mathbb{E} [ w_t^\top P^*_k w_t \mid h_t],
\end{split}
\end{equation}

\begin{equation}\label{eq:main2}
\begin{split}
&\mathbb{E} [ w_t^\top P^*_k w_t \mid h_t]=\mathbb{E} [ x_{t+1}^\top P^*_k x_{t+1} \mid h_t] - 
(\bar{\Theta}_*^\top z_t )^\top P^*_k (\bar{\Theta}_*^\top z_t ).
\end{split}
\end{equation}

\begin{equation}\label{eq:main3}
\begin{split}
x_t^{\top} Q x_t + \Tilde{u}_t^{\top} R \Tilde{u}_t  &= J(\tilde{\theta}_k) + x_t^\top P^*_k x_t 
-\mathbb{E} [ x_{t+1}^\top P^*_k x_{t+1} \mid h_t]\\
&+ (\bar{\Theta}_*^\top z_t )^\top P^*_k (\bar{\Theta}_*^\top z_t )
- (\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t )^\top P^*_k (\tilde{A}_kx_t+\Tilde{B}_k\Tilde{u}_t). 
\end{split}
\end{equation}

\begin{equation*}
\begin{split}
\mathbb{E}[c (x_t, u_t)] &= \mathbb{E}[x_t^{\top} Q x_t + u_t^{\top} R u_t] \\
&= J(\tilde{\theta}_k) + x_t^\top P^*_k x_t 
-\mathbb{E} [ x_{t+1}^\top P^*_k x_{t+1} \mid h_t]\\
&+ (\bar{\Theta}_*^\top z_t )^\top P^*_k (\bar{\Theta}_*^\top z_t )
- (\bar{\Theta}_k^\top z_t )^\top P^*_k (\bar{\Theta}_k^\top z_t ) + \mathbb{E}[\nu_t^{\top} \Tilde{B}_k^{\top}P^*_k\Tilde{B}_k\nu_t] +\mathbb{E}[\nu_t^{\top} R \nu_t],
\end{split}
