\label{lem:state_log}
For any $t = 1, \ldots, T$, the following inequality holds:
\[
\mathbf{1}_{F_t}\max_{j\leq t}|x_j| \leq C \left(\log\bigg(\frac{1}{\delta}\bigg)^2\sqrt{\log\bigg(\frac{t}{\delta}\bigg)}\right)^{d+1}
\]
for some constant $C > 0$ depending only on $d, m, \rho, M_\rho, \bar{L}_\nu$ and $S$.

\begin{equation*}
    \begin{split}
        (t(t+1))^{-1/\log \delta} &\leq (t(t+1))^{1/\log t}\\ 
        &\leq (2t^2)^{1/\log t}\\
        &=2^{1/\log t} t^{2/ \log t}\\
        &\leq e^3.
    \end{split}
\end{equation*}

\label{lem:abbasi_lem_18}
For any $t = 1, \ldots, T$, on the event $E_t$
\begin{equation*}
\max_{s\leq t,s\notin \mathcal{T}_t} |M_s^\top z_s| \leq GZ_t^{\frac{d}{d+1}} \beta_t(\delta)^{\frac{1}{2(d+1)}},
\end{equation*}
where $G=2\big(\frac{2Sd^{d+0.5}}{\sqrt{U}}\big)^{\frac{1}{d+1}}$ and $Z_t=\max_{s\leq t}|z_s|.$

\begin{equation*}
\begin{split}
    \beta_t(\delta)\geq |\tilde{\theta}_t-\theta_*|_{P_t} &= \sum_{i,i'=1}^{d}\sum_{j,j'=1}^{n}(\tilde{\theta}_t-\theta_*)_{d(j-1)+i}P_{d(j-1)+i,d(j'-1)+i'}(\tilde{\theta}_t-\theta_*)_{d(j'-1)+i'}\\
    & = \sum_{i,i'=1}^{d}\sum_{j,j'=1}^{n} (\tilde{\Theta}_t-\Theta_*)_{ij}(I_n)_{jj'}\bigg (\sum_{s=1}^{t-1}z_sz_s^{\top}+\lambda I_d\bigg )_{ii'}(\tilde{\Theta}_t-\Theta_*)_{i'j'}\\
    & = \sum_{i,i'=1}^{d}\sum_{j=1}^{n} (\tilde{\Theta}_t-\Theta_*)^{\top}_{ji}\bigg( \sum_{s=1}^{t-1}z_sz_s^{\top}+\lambda I_d\bigg )_{ii'}(\tilde{\Theta}_t-\Theta_*)_{i'j}\\
    &= \mathbf{tr}\left (M_t^\top \bigg (\sum_{s=1}^{t-1} z_s z_s^\top +\lambda I_d\bigg )M_t\right)\\
    &\geq \max_{1\leq s < t} |M_t^\top z_s|^2.
\end{split}
\end{equation*}

\begin{align*}
    \max_{s\leq t,s\notin \mathcal{T}_{t}}|M_s^{\top}z_s| &\leq  d\epsilon Z_t+2S\sqrt{\frac{d}{U}}\frac{1}{\epsilon^{n+d}}\max_{s\leq t,s\notin \mathcal{T}_{t}}\max_{1 \leq i \leq i(s)}|M_{\tilde t_i}^{\top}z_s|.
\end{align*}

\begin{align*}
\max_{s\leq t,s\notin \mathcal{T}_{t}}\max_{1 \leq i \leq i(s)}|M_{\tilde t_i}^{\top}z_s| &\leq \max_{i}\max_{s<\tilde t_i}|M_{\tilde t_i}^{\top}z_s| \\
& \leq \beta_t(\delta)^{\frac{1}{2}}.
\end{align*}

\label{lem:tall_matrix}
For two matrices $X$,$Y$ with the same number of rows and any $\bar\lambda>0$, we have
\[
\begin{bmatrix}
X^\top X & X^\top Y\\
Y^\top X & Y^\top Y
\end{bmatrix} \succeq
\begin{bmatrix}
\frac{\bar\lambda}{|Y|^2+\bar\lambda}X^\top X & 0\\
0 & -\bar\lambda I_{n_u}
\end{bmatrix}.
\]

\[
\begin{bmatrix}
X^\top X & X^\top Y\\
Y^\top X & Y^\top Y
\end{bmatrix} \succeq
\begin{bmatrix}
\frac{\bar\lambda}{|Y|^2+\bar\lambda}X^\top X & 0\\
0 & -\bar\lambda I_{n_u}
\end{bmatrix}.
\]

Since
\begin{align*}
    &\begin{bmatrix}
    X^\top Y(Y^{\top}Y+\bar\lambda I_d)^{-1} Y^{\top} X & X^{\top}Y \\
    Y^\top X & Y^{\top}Y+\bar\lambda I_{n_u}
    \end{bmatrix}\\
    &=
    \begin{bmatrix}
    X^\top Y(Y^{\top}Y+\bar\lambda I_d)^{-1/2}\\ 
    (Y^{\top}Y+\bar\lambda I_d)^{1/2}
    \end{bmatrix}
    \begin{bmatrix}
    (Y^{\top}Y+\bar\lambda I_d)^{-1/2}Y^\top X& 
    (Y^{\top}Y+\bar\lambda I_d)^{1/2}
    \end{bmatrix}\\
    &\succeq 0,
\end{align*}
it is straightforward to check that
\begin{align*}
    &\begin{bmatrix}
     X^{\top}X & X^{\top}Y \\
    Y^\top X & Y^{\top}Y\\
    \end{bmatrix}\\
    &\succeq 
    \begin{bmatrix}
        X^{\top}X-X^{\top}Y(Y^{\top}Y+\bar\lambda I_{n_u})^{-1}Y^{\top}X & 0\\
        0 & -\bar\lambda I_{n_u}\\
    \end{bmatrix}\\
    &= 
    \begin{bmatrix}
        X^{\top}(I-Y(Y^{\top}Y+\bar\lambda I_{n_u})^{-1}Y^{\top})X & 0\\
        0 & -\bar\lambda I_{n_u}\\
    \end{bmatrix}\\
    &\succeq
    \begin{bmatrix}
    \frac{\bar\lambda}{|Y|^2+\bar\lambda}Y^\top Y & 0\\
    0 & -\bar\lambda I_{n_u}
    \end{bmatrix},
\end{align*}
where the last inequality follows from the singular value decomposition and the relation
\[
I-Y(Y^{\top}Y+\bar\lambda I_{n_u})^{-1}Y^{\top} \succeq \frac{\bar\lambda}{|Y|^2+\bar\lambda}.
\]

\begin{align*}
    &\begin{bmatrix}
    X^\top Y(Y^{\top}Y+\bar\lambda I_d)^{-1} Y^{\top} X & X^{\top}Y \\
    Y^\top X & Y^{\top}Y+\bar\lambda I_{n_u}
    \end{bmatrix}\\
    &=
    \begin{bmatrix}
    X^\top Y(Y^{\top}Y+\bar\lambda I_d)^{-1/2}\\ 
    (Y^{\top}Y+\bar\lambda I_d)^{1/2}
    \end{bmatrix}
    \begin{bmatrix}
    (Y^{\top}Y+\bar\lambda I_d)^{-1/2}Y^\top X& 
    (Y^{\top}Y+\bar\lambda I_d)^{1/2}
    \end{bmatrix}\\
    &\succeq 0,
\end{align*}

\begin{align*}
    &\begin{bmatrix}
     X^{\top}X & X^{\top}Y \\
    Y^\top X & Y^{\top}Y\\
    \end{bmatrix}\\
    &\succeq 
    \begin{bmatrix}
        X^{\top}X-X^{\top}Y(Y^{\top}Y+\bar\lambda I_{n_u})^{-1}Y^{\top}X & 0\\
        0 & -\bar\lambda I_{n_u}\\
    \end{bmatrix}\\
    &= 
